11	/** Metadata for one column (ADR-0011, TD-09). Every column carries it. */
12	export type ColumnMeta =
13	  | { readonly personal: false }
14	  | {
15	      readonly personal: true;
16	      readonly category: PersonalDataCategory;
17	      /** Why the platform keeps it. */
18	      readonly purpose: string;
19	      /** The module that owns it. */
20	      readonly owner: string;
21	      /** How long the platform keeps it, for example "account lifetime + 3 years". */
22	      readonly retention: string;
23	    };
24	
25	export const notPersonal: ColumnMeta = { personal: false };
26	
27	type ColumnsOf<T extends Table> = T["_"]["columns"];
28	
29	const registry = new Map<Table, Record<string, ColumnMeta>>();
30	
31	/** Registers the metadata of every column of a table. The personal data check reads it. */
32	export function withDataMeta<T extends Table>(
33	  table: T,
34	  meta: { [K in keyof ColumnsOf<T>]: ColumnMeta },
35	): T {
36	  registry.set(table, meta as Record<string, ColumnMeta>);
37	  return table;
38	}
39	
40	export function dataMetaOf(table: Table): Record<string, ColumnMeta> | undefined {
41	  return registry.get(table);
42	}
