import type { AdvisorMasterData, CustomerMasterData, ErpPort } from "@provital/erp-port";
import type { Clock } from "../kernel";
import { systemClock } from "../kernel";

/**
 * The only module that reaches the ERP (T3-D-005, T3-AC-001).
 * Other modules call this public API; they never import the port or an adapter.
 */

export interface ErpRead<T> {
  readonly data: T;
  /** Where the data comes from, its version and the read time (T2-D-009). */
  readonly source: "erp";
  readonly sourceVersion: string;
  readonly readAt: string;
}

export type { AdvisorMasterData, CustomerMasterData };

export interface Integration {
  readCustomer(customerNumber: string): Promise<ErpRead<CustomerMasterData> | null>;
  readAdvisor(advisorNumber: string): Promise<ErpRead<AdvisorMasterData> | null>;
}

export interface IntegrationDeps {
  erp: ErpPort;
  clock?: Clock;
}

export function createIntegration({ erp, clock = systemClock }: IntegrationDeps): Integration {
  function read<T extends { sourceVersion: string }>(data: T | null): ErpRead<T> | null {
    if (!data) return null;
    return {
      data,
      source: "erp",
      sourceVersion: data.sourceVersion,
      readAt: clock.now().toISOString(),
    };
  }

  return {
    async readCustomer(customerNumber) {
      return read(await erp.readCustomer(customerNumber));
    },

    async readAdvisor(advisorNumber) {
      return read(await erp.readAdvisor(advisorNumber));
    },
  };
}

