import { describe, expect, it } from "vitest";
import type { Integration } from "../integration";
import { fixedClock, InMemoryEventBus } from "../kernel";
import { createIdentity, EmailAlreadyRegisteredError, InMemoryPersonRepository } from "./index";

/** A stub of the integration module's public API. Synthetic data only. */
const integration: Integration = {
  async readCustomer() {
    return null;
  },
  async readAdvisor(advisorNumber) {
    if (advisorNumber !== "B20001") return null;
    return {
      data: {
        advisorNumber: "B20001",
        givenName: "Anna",
        familyName: "Beraterin",
        email: "anna.beraterin@example.test",
        active: true,
        sourceVersion: "v2",
      },
      source: "erp",
      sourceVersion: "v2",
      readAt: "2027-01-05T08:00:00.000Z",
    };
  },
};

function setup() {
  const bus = new InMemoryEventBus();
  const identity = createIdentity({
    repo: new InMemoryPersonRepository(),
    bus,
    integration,
    clock: fixedClock("2027-01-05T08:00:00Z"),
  });
  return { bus, identity };
}

describe("identity", () => {
  it("T3-AC-003: keeps one person record per e-mail address", async () => {
    const { identity } = setup();
    await identity.registerPerson({
      email: "Erika@Example.test",
      givenName: "Erika",
      familyName: "Muster",
    });
    await expect(
      identity.registerPerson({ email: "erika@example.test", givenName: "E", familyName: "M" }),
    ).rejects.toBeInstanceOf(EmailAlreadyRegisteredError);
  });

  it("publishes identity.person-registered", async () => {
    const { bus, identity } = setup();
    const person = await identity.registerPerson({
      email: "max@example.test",
      givenName: "Max",
      familyName: "Beispiel",
    });
    expect(bus.published).toHaveLength(1);
    expect(bus.published[0]).toMatchObject({
      type: "identity.person-registered",
      payload: { personId: person.id },
    });
  });

  it("T3-D-005: reads advisor master data from the ERP through integration", async () => {
    const { identity } = setup();
    expect(await identity.getAdvisor("B20001")).toEqual({
      advisorNumber: "B20001",
      givenName: "Anna",
      familyName: "Beraterin",
      email: "anna.beraterin@example.test",
      active: true,
      sourceVersion: "v2",
      readAt: "2027-01-05T08:00:00.000Z",
    });
  });

  it("returns null when the ERP has no such advisor", async () => {
    const { identity } = setup();
    expect(await identity.getAdvisor("B99999")).toBeNull();
  });
});

