import { kernel } from "@provital/core";
import { describe, expect, it } from "vitest";
import { createApp } from "./index";

describe("worker composition", () => {
  it("wires the modules", async () => {
    const app = createApp();
    const person = await app.identity.registerPerson({
      email: "a@example.test",
      givenName: "A",
      familyName: "B",
    });
    expect(await app.identity.getPerson(person.id)).toEqual(person);
  });

  it("exposes advisor master data from the fake ERP as app.identity.getAdvisor", async () => {
    const app = createApp({ clock: kernel.fixedClock("2027-01-05T08:00:00Z") });
    expect(await app.identity.getAdvisor("B20001")).toEqual({
      advisorNumber: "B20001",
      givenName: "Anna",
      familyName: "Beraterin",
      email: "anna.beraterin@example.test",
      active: true,
      sourceVersion: "v2",
      readAt: "2027-01-05T08:00:00.000Z",
    });
    expect(await app.identity.getAdvisor("B99999")).toBeNull();
  });

  it("fails the advisor read when the ERP is unavailable", async () => {
    const app = createApp({ erp: { unavailable: true } });
    await expect(app.identity.getAdvisor("B20001")).rejects.toThrow("ERP unavailable");
  });
});

